package com.docuflow.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="activity_logs") public class ActivityLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Document document; @ManyToOne(optional=false) private User actor; @Column(nullable=false,length=80) private String action; @Column(length=500) private String detail; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected ActivityLog(){} public ActivityLog(Document d,User a,String action,String detail){document=d;actor=a;this.action=action;this.detail=detail;} public Long getId(){return id;} public String getAction(){return action;} public String getDetail(){return detail;} public User getActor(){return actor;} public Document getDocument(){return document;} public Instant getCreatedAt(){return createdAt;} }
